import numpy as np


class ViolationAwareBisectionES:
    """
    Feasibility-first (mu+lambda) mixed-integer ES with:
      * magnitude- and frequency-aware per-constraint weights (EMA-style multiplicative update),
      * explicit tracking of the dominant violated constraint (frequency x magnitude),
        with a cubic weight boost for it,
      * targeted pull moves: parents violating the dominant constraint are pulled far
        toward the feasible incumbent,
      * deeper boundary bisection (4 steps) between infeasible offspring and the incumbent,
      * per-individual log-normal self-adaptation of continuous step sizes,
      * type-aware integer mutations (binary flip, ordinal +-1, categorical resampling),
      * trust-region local search around the incumbent (1/5-type radius rule),
      * feasibility-adaptive move schedule and stagnation restarts,
      * duplicate cache (no budget cost).
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float).ravel()[:d]
        ub = np.asarray(func.bounds.ub, dtype=float).ravel()[:d]
        vtypes = [str(t) for t in func.variable_types][:d]
        width = ub - lb

        nv = np.ones(d, dtype=int)
        raw_nv = getattr(func, "n_values", None)
        if raw_nv is not None:
            raw_nv = np.asarray(raw_nv).ravel()
            for i in range(min(d, len(raw_nv))):
                if vtypes[i] != "continuous":
                    nv[i] = max(1, int(raw_nv[i]))

        cont = np.array([i for i in range(d) if vtypes[i] == "continuous"], dtype=int)
        ints = np.array([i for i in range(d) if vtypes[i] != "continuous"], dtype=int)
        ordn = np.array([vtypes[i] == "ordinal" for i in range(d)], dtype=bool)
        binm = np.array([vtypes[i] == "binary" for i in range(d)], dtype=bool)
        tau = 1.0 / np.sqrt(max(d, 1))

        def repair(X):
            X = np.array(X, dtype=float, copy=True)
            if cont.size:
                X[..., cont] = np.clip(X[..., cont], lb[cont], ub[cont])
            if ints.size:
                X[..., ints] = np.clip(np.rint(X[..., ints]), 0, nv[ints] - 1)
            return X

        def sample(n):
            X = np.empty((n, d))
            for i in cont:
                perm = np.random.permutation(n)
                u = (perm + np.random.rand(n)) / n
                X[:, i] = lb[i] + u * width[i]
            for i in ints:
                X[:, i] = np.random.randint(0, nv[i], size=n)
            return repair(X)

        # ---------------- state ----------------
        cache = {}
        state = {"used": 0, "best": None, "w": None, "dom": None,
                 "tr": 0.05, "lm_n": 0, "lm_s": 0,
                 "n_eval": 0, "n_feas": 0}

        def evaluate(x, sig):
            x = repair(x)
            kt = tuple(x.tolist())
            if kt in cache:
                return cache[kt]
            if state["used"] >= budget:
                return None
            f, g = func(x.copy())
            state["used"] += 1
            f = float(f)
            g = np.nan_to_num(np.atleast_1d(np.asarray(g, dtype=float)),
                              nan=1e6, posinf=1e6, neginf=0.0)
            gp = np.maximum(g, 0.0)
            feas = bool(np.all(gp <= 0.0)) and bool(np.isfinite(f))
            ind = {"x": x, "f": f, "g": gp, "feas": feas, "sig": float(sig)}
            cache[kt] = ind
            state["n_eval"] += 1
            state["n_feas"] += int(feas)
            if state["w"] is None:
                state["w"] = np.ones(len(gp))
            if feas and (state["best"] is None or f < state["best"]["f"]):
                state["best"] = ind
            return ind

        def ikey(ind):
            if ind["feas"]:
                return (0, ind["f"])
            w = state["w"]
            wv = float(np.dot(w, ind["g"])) if w is not None else float(np.sum(ind["g"]))
            if not np.isfinite(ind["f"]):
                wv += 1e6
            return (1, wv)

        def rank(pop):
            return sorted(pop, key=ikey)

        def feas_rate():
            if state["n_eval"] < 10:
                return 0.0
            return state["n_feas"] / state["n_eval"]

        # ---------------- operators ----------------
        def tournament(pop):
            n = len(pop)
            i, j = np.random.randint(n), np.random.randint(n)
            return pop[min(i, j)]

        def crossover(a, b):
            if np.random.rand() < 0.7:
                mask = np.random.rand(d) < 0.5
                return np.where(mask, a, b)
            return a.copy()

        def mutate(x, pm, sig):
            y = x.copy()
            if cont.size:
                m = np.random.rand(cont.size) < pm
                k = int(m.sum())
                if k > 0:
                    idx = cont[m]
                    if np.random.rand() < 0.1:
                        step = np.clip(np.random.standard_cauchy(k), -5, 5) * 0.5 * sig
                    else:
                        step = np.random.randn(k) * sig
                    y[idx] += step * width[idx]
            for i in ints[np.random.rand(ints.size) < pm]:
                if binm[i]:
                    y[i] = 1 - y[i]
                elif nv[i] <= 1:
                    continue
                elif ordn[i] and np.random.rand() < 0.7:
                    y[i] += 1 if np.random.rand() < 0.5 else -1
                else:
                    v = np.random.randint(0, nv[i] - 1)
                    y[i] = v if v < y[i] else v + 1
            return repair(y)

        def local_move(best_x, pop, sc):
            y = best_x.copy()
            if cont.size:
                if np.random.rand() < 0.5 and len(pop) >= 2:
                    r1, r2 = np.random.choice(len(pop), 2, replace=False)
                    p1 = pop[r1]["x"]
                    p2 = pop[r2]["x"]
                    F = np.random.uniform(0.3, 0.9)
                    diff = (p1 - p2)[cont] / np.maximum(width[cont], 1e-12)
                    cross = np.random.rand(cont.size) < 0.7
                    if not cross.any():
                        cross[np.random.randint(cont.size)] = True
                    tmp = y[cont] + F * diff * width[cont] * (sc / 0.05 if sc > 0 else 1.0)
                    y[cont] = np.where(cross, tmp, y[cont])
                else:
                    m = np.random.rand(cont.size) < 0.5
                    idx = cont[m]
                    if idx.size:
                        y[idx] += np.random.randn(idx.size) * sc * width[idx]
            for i in ints:
                if np.random.rand() < 1.0 / max(d, 1):
                    if binm[i]:
                        y[i] = 1 - y[i]
                    elif nv[i] > 1:
                        if ordn[i]:
                            y[i] += 1 if np.random.rand() < 0.5 else -1
                        else:
                            v = np.random.randint(0, nv[i] - 1)
                            y[i] = v if v < y[i] else v + 1
            return repair(y)

        def pull_move(a, best, dom):
            # targeted repair: parents violating the dominant constraint are pulled further
            if dom is not None and a["g"][dom] > 0 and np.random.rand() < 0.6:
                t = np.random.uniform(0.5, 0.95)
            else:
                t = np.random.uniform(0.2, 0.8)
            y = a["x"] + t * (best["x"] - a["x"])
            return mutate(y, 1.0 / d, 0.03)

        def bisect(x_inf, x_feas, steps=4):
            # locate the feasible boundary along the segment feasible -> infeasible
            out = []
            lo, hi = 0.0, 1.0
            for _ in range(steps):
                t = 0.5 * (lo + hi)
                y = x_feas + t * (x_inf - x_feas)
                e = evaluate(y, 0.02)
                if e is None:
                    break
                out.append(e)
                if e["feas"]:
                    lo = t
                else:
                    hi = t
            return out

        def update_tr(success):
            state["lm_n"] += 1
            state["lm_s"] += int(success)
            if state["lm_n"] >= 8:
                rate = state["lm_s"] / state["lm_n"]
                if rate > 0.2:
                    state["tr"] *= 1.5
                elif rate < 0.05:
                    state["tr"] *= 0.7
                if state["tr"] < 1e-3 and rate < 0.05:
                    state["tr"] = 0.1
                state["tr"] = float(np.clip(state["tr"], 1e-3, 0.5))
                state["lm_n"] = 0
                state["lm_s"] = 0

        def update_weights(pop):
            G = np.array([p["g"] for p in pop])
            infeas = [p for p in pop if not p["feas"]]
            if G.size == 0 or not infeas:
                return
            frac = np.mean(G > 0, axis=0)
            Gi = np.array([p["g"] for p in infeas])
            mag = np.mean(np.tanh(Gi), axis=0)  # magnitude of violation among infeasible
            w = state["w"].copy()
            score = frac + 0.5 * mag
            factor = np.clip(1.0 + 0.15 * (score - 0.3), 0.85, 1.25)
            w = w * factor
            # dominant constraint: frequency x magnitude
            dom_score = frac * (1.0 + mag)
            k = int(np.argmax(dom_score))
            state["dom"] = k
            if frac[k] > 0.2:
                w[k] *= 1.0 + 0.5 * frac[k] ** 3 + 0.2 * mag[k]
            w = np.clip(w, 0.05, 1e3)
            state["w"] = w / np.mean(w)

        # ---------------- initialisation ----------------
        mu = max(8, min(30, 3 * d))
        lam = mu
        init_n = min(max(4 * mu, 10 * d), max(1, budget // 2))

        pop = []
        for x in sample(init_n):
            e = evaluate(x, 0.2)
            if e is None:
                break
            pop.append(e)
        if not pop:
            return np.inf, None
        pop = rank(pop)[:mu]

        patience = 10
        stall = 0
        prev_key = ikey(pop[0])

        # ---------------- main loop ----------------
        while state["used"] < budget:
            update_weights(pop)
            pop = rank(pop)
            children = []

            fr = feas_rate()
            p_local = 0.35 if state["best"] is None else (0.45 if fr > 0.3 else 0.35)
            p_pull = 0.12
            p_bis = 0.05 if state["best"] is None else 0.10

            for _ in range(lam):
                if state["used"] >= budget:
                    break
                best = state["best"]
                r = np.random.rand()

                if best is not None and r < p_local:
                    sc = state["tr"] * 10 ** np.random.uniform(-0.5, 0.5)
                    sc = float(np.clip(sc, 1e-4, 0.5))
                    prev_best_f = best["f"]
                    child = local_move(best["x"], pop, sc)
                    e = evaluate(child, sc)
                    if e is None:
                        break
                    children.append(e)
                    update_tr(e["feas"] and e["f"] < prev_best_f)
                    continue

                if best is not None and r < p_local + p_pull:
                    infeas = [p for p in pop if not p["feas"]]
                    if infeas:
                        a = infeas[np.random.randint(len(infeas))]
                        child = pull_move(a, best, state["dom"])
                        e = evaluate(child, 0.03)
                        if e is None:
                            break
                        children.append(e)
                        continue

                if best is not None and r < p_local + p_pull + p_bis:
                    infeas = [p for p in pop if not p["feas"]]
                    if infeas:
                        a = infeas[np.random.randint(len(infeas))]
                        got = bisect(a["x"], best["x"])
                        if not got and state["used"] >= budget:
                            break
                        children.extend(got)
                        continue

                a = tournament(pop)
                b = tournament(pop)
                sp = a["sig"] if np.random.rand() < 0.5 else b["sig"]
                sig_c = float(np.clip(sp * np.exp(tau * np.random.randn()), 1e-4, 0.5))
                pm = float(np.random.choice([1.0 / d, 2.0 / d, 0.1, 0.3]))
                child = mutate(crossover(a["x"], b["x"]), pm, sig_c)
                e = evaluate(child, sig_c)
                if e is None:
                    break
                children.append(e)

            if not children:
                break

            pop = rank(pop + children)[:mu]

            cur_key = ikey(pop[0])
            if cur_key < prev_key:
                prev_key = cur_key
                stall = 0
            else:
                stall += 1

            # stagnation: diversify while keeping elite and incumbent
            if stall >= patience and state["used"] < budget:
                newp = [pop[0]]
                best = state["best"]
                if best is not None and best is not pop[0]:
                    newp.append(best)
                n_new = mu - len(newp)
                n_lhs = n_new // 2
                for x in sample(n_lhs):
                    e = evaluate(x, 0.2)
                    if e is None:
                        break
                    newp.append(e)
                if best is not None:
                    for k in range(n_new - n_lhs):
                        if state["used"] >= budget:
                            break
                        sg = 0.05 if k % 2 == 0 else 0.2
                        x = mutate(best["x"], 0.3, sg)
                        e = evaluate(x, sg)
                        if e is None:
                            break
                        newp.append(e)
                pop = rank(newp)[:mu]
                stall = 0
                state["tr"] = 0.1
                state["lm_n"] = 0
                state["lm_s"] = 0
                prev_key = ikey(pop[0])

        best = state["best"]
        if best is None:
            return np.inf, None
        return best["f"], best["x"]
